B.a14=s(["\u738b\u6fec\u6a13\u8239\u4e0b\u76ca\u5dde\uff0c","\u91d1\u9675\u738b\u6c23\u9eef\u7136\u6536\u3002","\u5343\u5c0b\u9435\u9396\u6c88\u6c5f\u5e95\uff0c","\u4e00\u7247\u964d\u65db\u51fa\u77f3\u982d\u3002","\u4eba\u4e16\u5e7e\u56de\u50b7\u5f80\u4e8b\uff0c","\u5c71\u5f62\u4f9d\u820a\u6795\u5bd2\u6d41\u3002","\u5f9e\u4eca\u56db\u6d77\u70ba\u5bb6\u65e5\uff0c","\u6545\u58d8\u856d\u856d\u8606\u837b\u79cb\u3002"],t.s)
B.alz=s(["Since Wang Jun brought his towering ships down from Yizhou,","The royal ghost has pined in the city of Nanjing.","Ten thousand feet of iron chain were sunk here to the bottom  --","And then came the flag of surrender on the Wall of Stone....","Cycles of change have moved into the past,","While still this mountain dignity has commanded the cold river;","And now comes the day of the Chinese world united,","And the old forts fill with ruin and with autumn reeds."],t.s)
