B.abJ=s(["\u9591\u5750\u60b2\u541b\u4ea6\u81ea\u60b2\uff0c","\u767e\u5e74\u90fd\u662f\u5e7e\u591a\u6642\uff1f","\u9127\u6538\u7121\u5b50\u5c0b\u77e5\u547d\uff0c","\u6f58\u5cb3\u60bc\u4ea1\u7336\u8cbb\u8a5e\u3002","\u540c\u7a74\u7a85\u51a5\u4f55\u6240\u671b\uff1f","\u4ed6\u751f\u7de3\u6703\u66f4\u96e3\u671f\u3002","\u60df\u5c07\u7d42\u591c\u9577\u958b\u773c\uff0c","\u5831\u7b54\u5e73\u751f\u672a\u5c55\u7709\u3002"],t.s)
B.Zl=s(["I sit here alone, mourning for us both.","How many years do I lack now of my threescore and ten?","There have been better men than I to whom heaven denied a son,","There was a poet better than I whose dead wife could not hear him.","What have I to hope for in the darkness of our tomb?","You and I had little faith in a meeting after death-","Yet my open eyes can see all night","That lifelong trouble of your brow."],t.s)
